code_sketch:
struct ast {
    enum { AST_NUM, AST_ADD, AST_MUL } tag;
    union { long num; struct { struct ast *l, *r; } bin; } as;
};
long eval(const struct ast *n, const struct ctx *c) {
    switch (n->tag) {
    case AST_NUM: return n->as.num;
    case AST_ADD: return eval(n->as.bin.l, c) + eval(n->as.bin.r, c);
    case AST_MUL: return eval(n->as.bin.l, c) * eval(n->as.bin.r, c);
    }
    abort(); /* unreachable once -Wswitch -Werror is clean */
}

